import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomBytes } from 'node:crypto';

const DEFAULT_FILE = join(process.cwd(), 'data', 'books.json');

/**
 * The books live in a single JSON file. Every mutation is a read-modify-write of
 * the whole file, so writes are queued (see `queue` below) and land via a
 * tmp-file rename to avoid a half-written file if the process dies mid-save.
 */
export function createStore({ file = process.env.BOOKS_FILE || DEFAULT_FILE } = {}) {
  // Serialises mutations: each one waits for the previous to finish, so two
  // concurrent requests can't both read the old list and clobber each other.
  let queue = Promise.resolve();

  async function readAll() {
    let raw;
    try {
      raw = await readFile(file, 'utf8');
    } catch (err) {
      if (err.code === 'ENOENT') return [];
      throw err;
    }
    if (!raw.trim()) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  }

  async function writeAll(books) {
    await mkdir(dirname(file), { recursive: true });
    const tmp = `${file}.${process.pid}.tmp`;
    await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
    await rename(tmp, file);
  }

  function mutate(fn) {
    const run = queue.then(async () => {
      const books = await readAll();
      const result = await fn(books);
      await writeAll(books);
      return result;
    });
    // Keep the chain alive even if this mutation rejected, so one failure
    // doesn't wedge every later write.
    queue = run.then(
      () => undefined,
      () => undefined
    );
    return run;
  }

  return {
    file,

    list() {
      return readAll();
    },

    async get(id) {
      const books = await readAll();
      return books.find((b) => b.id === id) ?? null;
    },

    /** @returns {Promise<object>} the created book */
    add({ title, author, notes, now = new Date() }) {
      const cleanTitle = String(title ?? '').trim();
      if (!cleanTitle) throw new ValidationError('A title is required.');

      return mutate((books) => {
        const book = {
          id: makeId(cleanTitle, books),
          title: cleanTitle,
          author: String(author ?? '').trim(),
          notes: String(notes ?? '').trim(),
          status: 'reading',
          startedAt: now.toISOString(),
          finishedAt: null,
        };
        books.unshift(book);
        return book;
      });
    },

    /** @returns {Promise<object|null>} the updated book, or null if unknown */
    finish(id, { now = new Date() } = {}) {
      return mutate((books) => {
        const book = books.find((b) => b.id === id);
        if (!book) return null;
