export function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const STYLES = `
  :root {
    --bg: #fbf9f5;
    --card: #fff;
    --ink: #1d1b17;
    --muted: #6d675d;
    --line: #e5e0d6;
    --accent: #7a4a2b;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #17161a;
      --card: #201f24;
      --ink: #f2efe9;
      --muted: #a49d92;
      --line: #35333a;
      --accent: #d9a273;
    }
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 2.5rem 1.25rem 4rem;
    background: var(--bg);
    color: var(--ink);
    font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  main { max-width: 44rem; margin: 0 auto; }
  a { color: var(--accent); }
  h1 { font-size: 1.6rem; margin: 0 0 1.75rem; letter-spacing: -0.01em; }
  h2 {
    font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.09em;
    color: var(--muted); margin: 2.25rem 0 0.75rem;
  }
  .card {
    background: var(--card); border: 1px solid var(--line);
    border-radius: 10px; padding: 1rem 1.15rem;
  }
  ul.shelf { list-style: none; margin: 0; padding: 0; display: grid; gap: 0.6rem; }
  ul.shelf li { display: flex; align-items: baseline; gap: 0.75rem; }
  ul.shelf .who { flex: 1; min-width: 0; }
  ul.shelf .title { font-weight: 600; text-decoration: none; }
  ul.shelf .title:hover { text-decoration: underline; }
  ul.shelf .author, .meta { color: var(--muted); font-size: 0.9rem; }
  .empty { color: var(--muted); font-style: italic; }
  form.inline { margin: 0; }
  label { display: block; font-size: 0.85rem; color: var(--muted); margin-bottom: 0.3rem; }
  input[type=text], textarea {
    width: 100%; padding: 0.55rem 0.65rem; font: inherit; color: var(--ink);
    background: var(--bg); border: 1px solid var(--line); border-radius: 7px;
  }
  textarea { min-height: 7rem; resize: vertical; }
  .field { margin-bottom: 0.9rem; }
  .row { display: grid; gap: 0.9rem; grid-template-columns: 1fr 1fr; }
  @media (max-width: 33rem) { .row { grid-template-columns: 1fr; } }
  button {
    font: inherit; cursor: pointer; border-radius: 7px; padding: 0.45rem 0.85rem;
    border: 1px solid var(--line); background: var(--card); color: var(--ink);
  }
  button:hover { border-color: var(--accent); color: var(--accent); }
  button.primary { background: var(--accent); border-color: var(--accent); color: var(--bg); }
  button.primary:hover { filter: brightness(1.08); color: var(--bg); }
  button.link {
    border: 0; background: none; color: var(--muted); padding: 0;
    font-size: 0.9rem; text-decoration: underline;
  }
  .error {
    background: #fdeceb; border: 1px solid #f0b6b1; color: #8a2018;
    padding: 0.6rem 0.8rem; border-radius: 7px; margin-bottom: 1.25rem;
  }
  @media (prefers-color-scheme: dark) {
    .error { background: #3a1f1d; border-color: #6b332e; color: #f4b8b1; }
  }
  .back { display: inline-block; margin-bottom: 1.5rem; font-size: 0.9rem; }
  .notes { white-space: pre-wrap; margin: 0; }
  hr { border: 0; border-top: 1px solid var(--line); margin: 1.5rem 0; }
  .actions { display: flex; gap: 0.75rem; align-items: center; margin-top: 1rem; }
`;

function layout({ title, body }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${STYLES}</style>
</head>
<body>
<main>
${body}
</main>
</body>
</html>
`;
}

function shelfItem(book) {
  const author = book.author
    ? `<span class="author">by ${escapeHtml(book.author)}</span>`
    : '';
  const action =
    book.status === 'finished'
      ? `<span class="meta">${escapeHtml(formatDate(book.finishedAt))}</span>`
      : `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
           <button type="submit">Mark finished</button>
         </form>`;
  return `<li>
    <span class="who">
      <a class="title" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
      ${author}
    </span>
    ${action}
  </li>`;
}

function shelfList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  return `<ul class="shelf">${books.map(shelfItem).join('')}</ul>`;
}

export function renderHome({ reading, finished, error, draft = {} }) {
  const body = `
<h1>My books</h1>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}

<h2>Currently reading</h2>
${shelfList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${shelfList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
<form class="card" method="post" action="/books">
  <div class="row">
    <div class="field">
      <label for="title">Title</label>
      <input id="title" name="title" type="text" required value="${escapeHtml(draft.title)}">
    </div>
    <div class="field">
      <label for="author">Author</label>
      <input id="author" name="author" type="text" value="${escapeHtml(draft.author)}">
    </div>
  </div>
  <div class="field">
    <label for="notes">Notes <span class="meta">(optional)</span></label>
    <textarea id="notes" name="notes">${escapeHtml(draft.notes)}</textarea>
  </div>
  <button class="primary" type="submit">Add book</button>
</form>
`;
  return layout({ title: 'My books', body });
}

export function renderBook({ book, saved }) {
  const author = book.author
    ? `<p class="meta">by ${escapeHtml(book.author)}</p>`
    : '<p class="meta">Author unknown</p>';

  const status =
    book.status === 'finished'
      ? `Finished ${escapeHtml(formatDate(book.finishedAt))}`
      : `Started ${escapeHtml(formatDate(book.startedAt))}`;

  const action =
    book.status === 'finished'
      ? `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/reopen">
           <button type="submit">Move back to reading</button>
         </form>`
      : `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
           <button class="primary" type="submit">Mark finished</button>
         </form>`;

  const body = `
<a class="back" href="/">&larr; All books</a>
<h1>${escapeHtml(book.title)}</h1>
${author}
<p class="meta">${status}</p>

<div class="actions">${action}</div>

<hr>

<h2>My notes</h2>
${saved ? '<p class="meta">Notes saved.</p>' : ''}
<form class="card" method="post" action="/books/${encodeURIComponent(book.id)}/notes">
  <div class="field">
    <label for="notes">What I thought</label>
    <textarea id="notes" name="notes">${escapeHtml(book.notes)}</textarea>
  </div>
  <button type="submit">Save notes</button>
</form>
`;
  return layout({ title: `${book.title} — My books`, body });
}

export function renderNotFound() {
  const body = `
<h1>Not found</h1>
<p class="meta">That book isn't on the shelf.</p>
<a class="back" href="/">&larr; All books</a>
`;
  return layout({ title: 'Not found — My books', body });
}

function formatDate(iso) {
  if (!iso) return '';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

