import { createServer } from 'node:http';

import { createStore, shelve, ValidationError } from './store.js';
import { renderBook, renderHome, renderNotFound } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;

export function createApp({ store = createStore() } = {}) {
  return createServer((req, res) => {
    handle(req, res, store).catch((err) => {
      console.error(err);
      if (!res.headersSent) send(res, 500, 'text/plain; charset=utf-8', 'Something went wrong.');
      else res.end();
    });
  });
}

async function handle(req, res, store) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const path = url.pathname.replace(/\/+$/, '') || '/';
  const method = req.method === 'HEAD' ? 'GET' : req.method;

  if (method === 'GET' && path === '/') {
    return sendHtml(res, 200, renderHome({ ...shelve(await store.list()) }));
  }

  if (method === 'GET' && path === '/books') {
    return redirect(res, '/');
  }

  // A book's own URL — this is the link you send someone.
  const detail = path.match(/^\/books\/([^/]+)$/);
