import { createServer } from 'node:http';

import { createStore, shelve, ValidationError } from './store.js';
import { renderBook, renderHome, renderNotFound } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;

export function createApp({ store = createStore() } = {}) {
  return createServer((req, res) => {
    handle(req, res, store).catch((err) => {
      console.error(err);
      if (!res.headersSent) send(res, 500, 'text/plain; charset=utf-8', 'Something went wrong.');
      else res.end();
    });
  });
}

