import { mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { beforeEach, describe, expect, it } from 'vitest';

import { createStore, shelve, ValidationError } from '../src/store.js';

let store;

beforeEach(async () => {
  const dir = await mkdtemp(join(tmpdir(), 'books-'));
  store = createStore({ file: join(dir, 'books.json') });
});

describe('store', () => {
  it('starts empty when the file does not exist yet', async () => {
    expect(await store.list()).toEqual([]);
  });

  it('adds a book as currently reading', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Sand.' });

    expect(book).toMatchObject({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Sand.',
      status: 'reading',
      finishedAt: null,
    });
    expect(book.id).toMatch(/^dune-[0-9a-f]{6}$/);
    expect(await store.list()).toHaveLength(1);
  });

  it('persists to the JSON file so books survive a restart', async () => {
    await store.add({ title: 'Piranesi' });

    const onDisk = JSON.parse(await readFile(store.file, 'utf8'));
    expect(onDisk).toHaveLength(1);

    const reopened = createStore({ file: store.file });
    expect((await reopened.list())[0].title).toBe('Piranesi');
  });

  it('rejects a book with no title', async () => {
    await expect(store.add({ title: '   ' })).rejects.toThrow(ValidationError);
    expect(await store.list()).toEqual([]);
  });

  it('defaults a missing author and notes to empty strings', async () => {
    const book = await store.add({ title: 'Untitled' });
    expect(book.author).toBe('');
    expect(book.notes).toBe('');
  });

  it('gives two books with the same title distinct ids', async () => {
    const a = await store.add({ title: 'Dune' });
    const b = await store.add({ title: 'Dune' });
    expect(a.id).not.toBe(b.id);
  });

  it('marks a book finished and stamps the date', async () => {
    const { id } = await store.add({ title: 'Dune' });

    const finished = await store.finish(id, { now: new Date('2026-08-26T10:00:00Z') });
    expect(finished.status).toBe('finished');
    expect(finished.finishedAt).toBe('2026-08-26T10:00:00.000Z');
    expect((await store.get(id)).status).toBe('finished');
  });

  it('moves a finished book back to reading', async () => {
    const { id } = await store.add({ title: 'Dune' });
    await store.finish(id);

    const reopened = await store.reopen(id);
    expect(reopened.status).toBe('reading');
    expect(reopened.finishedAt).toBeNull();
  });

  it('updates notes', async () => {
    const { id } = await store.add({ title: 'Dune' });
    await store.setNotes(id, '  Spice must flow.  ');
    expect((await store.get(id)).notes).toBe('Spice must flow.');
  });

  it('returns null for an unknown book', async () => {
    expect(await store.get('nope')).toBeNull();
    expect(await store.finish('nope')).toBeNull();
    expect(await store.reopen('nope')).toBeNull();
    expect(await store.setNotes('nope', 'x')).toBeNull();
  });

  it('does not lose writes when mutations overlap', async () => {
    await Promise.all(
      Array.from({ length: 10 }, (_, i) => store.add({ title: `Book ${i}` }))
    );
    expect(await store.list()).toHaveLength(10);
  });

  it('treats an empty or non-array file as an empty shelf', async () => {
    await writeFile(store.file, '', 'utf8');
    expect(await store.list()).toEqual([]);

    await writeFile(store.file, '{}', 'utf8');
    expect(await store.list()).toEqual([]);
  });
});

describe('shelve', () => {
  it('splits reading from finished, newest finished first', () => {
    const { reading, finished } = shelve([
      { title: 'A', status: 'reading' },
      { title: 'B', status: 'finished', finishedAt: '2026-01-01T00:00:00.000Z' },
      { title: 'C', status: 'finished', finishedAt: '2026-06-01T00:00:00.000Z' },
    ]);

    expect(reading.map((b) => b.title)).toEqual(['A']);
    expect(finished.map((b) => b.title)).toEqual(['C', 'B']);
  });
});

