import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { createApp } from '../src/server.js';
import { createStore } from '../src/store.js';

let server;
let base;
let store;

beforeEach(async () => {
  const dir = await mkdtemp(join(tmpdir(), 'books-http-'));
  store = createStore({ file: join(dir, 'books.json') });
  server = createApp({ store });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(() => new Promise((resolve) => server.close(resolve)));

const get = (path) => fetch(base + path, { redirect: 'manual' });

const post = (path, fields) =>
  fetch(base + path, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
  });

describe('home page', () => {
  it('shows both shelves with empty states', async () => {
    const res = await get('/');
    const html = await res.text();

    expect(res.status).toBe(200);
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('lists reading and finished books with links to each book', async () => {
    const reading = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const done = await store.add({ title: 'Piranesi', author: 'Susanna Clarke' });
    await store.finish(done.id);

    const html = await (await get('/')).text();

    expect(html).toContain(`href="/books/${reading.id}"`);
    expect(html).toContain(`href="/books/${done.id}"`);
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('Susanna Clarke');
  });
});

describe('adding a book', () => {
  it('saves the book and redirects home', async () => {
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Sand.' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const books = await store.list();
    expect(books).toHaveLength(1);
    expect(books[0]).toMatchObject({ title: 'Dune', status: 'reading', notes: 'Sand.' });
  });

  it('re-renders the form with an error when the title is missing', async () => {
    const res = await post('/books', { title: '', author: 'Nobody' });
    const html = await res.text();

    expect(res.status).toBe(400);
    expect(html).toContain('A title is required.');
    expect(html).toContain('value="Nobody"'); // keeps what was typed
    expect(await store.list()).toEqual([]);
  });
});

describe('book page', () => {
  it('shows title, author and notes at a shareable URL', async () => {
    const book = await store.add({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'The spice must flow.',
    });

    const res = await get(`/books/${book.id}`);
    const html = await res.text();

    expect(res.status).toBe(200);
    expect(html).toContain('Dune');
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('The spice must flow.');
  });

  it('404s for an unknown book', async () => {
    const res = await get('/books/does-not-exist');
    expect(res.status).toBe(404);
    expect(await res.text()).toContain("isn't on the shelf");
  });

  it('escapes HTML in book fields', async () => {
    const book = await store.add({ title: '<script>alert(1)</script>', author: '"x"' });
    const html = await (await get(`/books/${book.id}`)).text();

    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
  });

  it('saves notes and redirects back to the book', async () => {
    const book = await store.add({ title: 'Dune' });

    const res = await post(`/books/${book.id}/notes`, { notes: 'Book two is better.' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(`/books/${book.id}?saved=1`);
    expect((await store.get(book.id)).notes).toBe('Book two is better.');
  });
});

describe('finishing a book', () => {
  it('marks it finished and returns home when done from the shelf', async () => {
    const book = await store.add({ title: 'Dune' });

    const res = await post(`/books/${book.id}/finish`, { return: '/' });

    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');
    expect((await store.get(book.id)).status).toBe('finished');
  });

  it('returns to the book page when done from there', async () => {
    const book = await store.add({ title: 'Dune' });

    const res = await post(`/books/${book.id}/finish`, { return: `/books/${book.id}` });
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
  });

  it('can be undone', async () => {
    const book = await store.add({ title: 'Dune' });
    await post(`/books/${book.id}/finish`, {});

    await post(`/books/${book.id}/reopen`, {});
    expect((await store.get(book.id)).status).toBe('reading');
  });

  it('404s when finishing an unknown book', async () => {
    const res = await post('/books/nope/finish', {});
    expect(res.status).toBe(404);
  });

  it('ignores an off-site return target', async () => {
    const book = await store.add({ title: 'Dune' });

    const res = await post(`/books/${book.id}/finish`, { return: '//evil.example.com' });
    expect(res.headers.get('location')).toBe('/');
  });
});

describe('routing', () => {
  it('404s an unknown path', async () => {
    expect((await get('/nope')).status).toBe(404);
  });

  it('tolerates a trailing slash', async () => {
    const book = await store.add({ title: 'Dune' });
    expect((await get(`/books/${book.id}/`)).status).toBe(200);
  });
});

